SELECT p.gender, CASE WHEN p.age >= 75 THEN '75+' ELSE CAST(p.age AS TEXT) END AS age_group, d.itemid, d.value, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, SUM(CASE WHEN i.intime IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(i.subject_id), 0) AS icu_admission_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.subject_id = i.subject_id AND a.hadm_id = i.stay_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id AND l.charttime = i.intime JOIN d_labitems d ON l.itemid = d.itemid WHERE p.gender = 'F' AND p.age BETWEEN 69 AND 79 AND d.itemid IN (1557071, 1557072) GROUP BY p.gender, age_group, d.itemid, d.value ORDER BY p.gender, age_group, d.itemid, d.value NULLS LAST;